<?php
require_role('admin');try{$f=admin_audit_filter();}catch(RuntimeException $e){http_response_code(422);admin_page_start('Audit log');echo '<div class="alert error">'.e($e->getMessage()).'</div><a href="index.php?page=audit">Reset filters</a>';admin_page_end();return;}$v=$f['values'];$total=(int)q('SELECT COUNT(*) FROM audit_log a'.$f['sql'],$f['params'])->fetchColumn();$max=max(1,(int)ceil($total/25));$pn=min($max,max(1,(int)($_GET['p']??1)));$rows=q('SELECT a.*,u.name FROM audit_log a LEFT JOIN users u ON u.id=a.actor_id'.$f['sql'].' ORDER BY a.id DESC LIMIT 25 OFFSET '.(($pn-1)*25),$f['params'])->fetchAll();
admin_page_start('Audit log','Search the complete activity history. Each report also keeps its own event timeline.');
?><form class="panel admin-filter-grid" method="get"><input type="hidden" name="page" value="audit"><?php foreach(['from'=>'From date','to'=>'To date'] as $k=>$label):?><label><?=$label?><input type="date" name="<?=$k?>" value="<?=e($v[$k])?>"></label><?php endforeach;?><label>Actor<select name="actor"><option value="">All accounts</option><?php foreach(q('SELECT id,name FROM users ORDER BY name')->fetchAll() as $u):?><option value="<?=$u['id']?>" <?=$v['actor']==$u['id']?'selected':''?>><?=e($u['name'])?></option><?php endforeach;?></select></label><label>Action<select name="event"><option value="">All actions</option><?php foreach(q('SELECT DISTINCT action FROM audit_log ORDER BY action')->fetchAll() as $r):?><option value="<?=e($r['action'])?>" <?=$v['action']===$r['action']?'selected':''?>><?=e(admin_action_label($r['action']))?></option><?php endforeach;?></select></label><label>Issue ID<input type="number" min="1" name="issue" value="<?=$v['issue']?:''?>" placeholder="e.g. 12"></label><div class="admin-filter-actions"><button class="button secondary">Apply filters</button><a class="text-link" href="index.php?page=audit">Reset</a></div></form>
<div class="admin-section-heading"><h2><?=$total?> matching activities</h2><?php $query=$_GET;$query['page']='audit_export';unset($query['p']);?><a class="button secondary" href="?<?=e(http_build_query($query))?>">Export filtered CSV ↓</a></div><section class="panel no-pad"><?php if(!$rows):?><div class="admin-empty"><h3>No activities match</h3><p>Try a wider date range or reset the filters.</p></div><?php else:?><div class="table-wrap"><table><thead><tr><th>When</th><th>Who</th><th>Action</th><th>Details</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['name']?:'Unavailable account')?></td><td><?=e(admin_action_label($r['action']))?><small class="muted"><?=e($r['action'])?></small></td><td><?=e(admin_audit_details($r['action'],$r['details']))?><?php $change=json_decode($r['details'],true);if(is_array($change)&&($change['format']??'')==='civic-change-1'):?><details class="audit-change"><summary>Before / after and reason</summary><dl><dt>Before</dt><dd><?=e(json_encode($change['before'],JSON_UNESCAPED_UNICODE))?></dd><dt>After</dt><dd><?=e(json_encode($change['after'],JSON_UNESCAPED_UNICODE))?></dd><dt>Reason</dt><dd><?=e($change['reason'])?></dd></dl></details><?php endif;?><?php if($ids=admin_audit_issue_ids($r['action'],$r['details'])):?><div class="admin-issue-links"><?php foreach($ids as $id):?><a href="index.php?page=issue&amp;id=<?=(int)$id?>">Issue #<?=(int)$id?> →</a><?php endforeach;?></div><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;admin_pager($pn,$max,$total);?></section><?php admin_page_end();
